    def _size_for_entry(self, price):
        stop_distance = price * self.p.stop_pct
        if stop_distance <= 0:
            return 0
        return int((self.broker.getvalue() * self.p.risk_pct) / stop_distance)

    def _enter_long(self):
        size = self._size_for_entry(self.data.close[0])
        if size > 0:
            self.order = self.buy(size=size)

    def _enter_short(self):
        size = self._size_for_entry(self.data.close[0])
        if size > 0:
            self.order = self.sell(size=size)

    def _exit_position(self):
        # cancel any live stop before closing, else it can fire against a flat
        # position and open an unintended reverse position
        if self.stop_order is not None:
            self.cancel(self.stop_order)
        self.close()

    def next(self):
        bar_date = self.data.datetime.date(0)
        if self.current_date is None or bar_date != self.current_date:
            self.current_date = bar_date
            self.day_open = self.data.open[0]
            self.day_high = self.data.high[0]
            self.day_low = self.data.low[0]
        else:
            self.day_high = max(self.day_high, self.data.high[0])
            self.day_low = min(self.day_low, self.data.low[0])

        if not self.position and self.order is None and self.last_day_high is not None:
            if self.streak_dir == 'red' and self.streak_count >= self.p.streak_len:
                if self.data.close[0] > self.last_day_high:
                    self._enter_long()
            elif self.streak_dir == 'green' and self.streak_count >= self.p.streak_len:
                if self.data.close[0] < self.last_day_low:
                    self._enter_short()

        bar_time = self.data.datetime.time(0)
        # feed's fixed regular session is 09:30-15:55; no calendar import is
        # allowed, so the known session close bar is hardcoded
        is_session_end = (bar_time.hour == 15 and bar_time.minute == 55)

        if is_session_end:
            day_close = self.data.close[0]

            if self.p.mode == 'day':
                if day_close > self.day_open:
                    color = 'green'
                elif day_close < self.day_open:
                    color = 'red'
                else:
                    color = None
            else:
                color = None
                if self.prev_close is not None:
                    if day_close > self.prev_close:
                        color = 'green'
                    elif day_close < self.prev_close:
                        color = 'red'

            if self.position:
                if self.p.mode == 'day':
                    self._exit_position()
                elif self.p.mode == 'swing':
                    is_long = self.position.size > 0
                    if (is_long and color == 'red') or (not is_long and color == 'green'):
                        self._exit_position()

            if color is None:
                self.streak_dir = None
                self.streak_count = 0
            elif color == self.streak_dir:
                self.streak_count += 1
            else:
                self.streak_dir = color
                self.streak_count = 1

            self.last_day_high = self.day_high
            self.last_day_low = self.day_low
            self.prev_close = day_close
